return {
  [695033619586816] = "Em transe, você mergulha no fundo do Lago do Mar das Flores, onde dois mundos chamados \"Ordem\" e \"Caos\" estão escondidos...",
  [281546917428736] = "Todos os presentes do destino já foram marcados com um preço no escuro.",
  [695033619586304] = "O desejo nunca mente, o jogo de azar atrai você. Veja através da verdade das balas e torne-se o vencedor do desejo.",
  [695033619583488] = "O que o olho nu vê não é necessariamente a verdade. Um excelente detetive sabe buscar respostas nos mortos.",
  [646721411547136] = "Dica 6 do Gambito do Tolo (espaço reservado)",
  [646721411483136] = "O olhar será lançado do céu estrelado, a terra será dilacerada e tudo no mundo deixará de existir.",
  [646721411514368] = "Azik Eggers foi o Cônsul da Morte do Império Balam na Quarta Época, e agora é um Sequência 2 Anjo da Morte Caminho.",
  [83769847451136] = "O Louco que não pertence a esta época, o misterioso governante acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce a boa sorte.",
  [646721411555584] = "Para um Espreitador de Mistérios com o talento Sábio, é recomendado carregar Refração da Luz, Roupas Novas do Imperador, Olhos de Espreitador de Mistérios e Gambito dos Séculos para o combate.",
  [646721411555328] = "Para um Espreitador de Mistérios com talento Acadêmico, é recomendado carregar Perseguição de Conhecimento, Refração de Luz, Areia Estelar e Gambito das Eras para combate.",
  [646721411555072] = "Para um guerreiro com o talento Dawn, é recomendado carregar Demon Hunter Instant Slash, Slash of Glory, Twilight Combo Slash e Greatsword Slash para combate.",
  [646721411554816] = "Para um Guerreiro com o talento Crepúsculo, é recomendado carregar Demon Hunter Instant Slash, Slash of Glory, Sunset Hurricane e Greatsword Slash para combate.",
  [646721411554560] = "Para um Aprendiz com o talento Star Patrol, é recomendado carregar Nebula Aria, Spirit World Travel, Star Positioning e Escape Trick para combate.",
  [646721411554304] = "Para um Aprendiz com o talento Flash Strike, é recomendado carregar Nebula Aria, Trick Performance, Exile e Space Cage para combate.",
  [646721411554048] = "Para um Vidente com o talento Espiritualidade, é recomendado carregar Air Bullet, Tarot Array, Miracle Card Rain e Fool's Blessing para o combate.",
  [646721411553792] = "Para um Vidente com o talento Destino, é recomendado carregar Card Flying Dagger, Tarot Array, Miracle Card Rain e Card Master para combate.",
  [646721411553536] = "Para um Espectador com o talento Dragon Might, é recomendado carregar Insight, Dream Weaving, Mental Plague e Deterrence para combate.",
  [646721411553280] = "Para um Espectador com talento Pacificar, é recomendado levar Análise de Sonhos, Orientação Mental, Sugestão Psicológica e Manipulação de Consciência para combate.",
  [646721411553024] = "Para um Bardo com o talento Veredicto Sagrado, é recomendado carregar Unshadowed Spear, Purifying Slash, Hurricane Axe e Holy Light Purification para combate.",
  [646721411552768] = "Para um Bardo com o talento Hino, é recomendado carregar Punição, Corte Purificador, Juramento Solar e Purificação da Luz Sagrada para o combate.",
  [646721411552512] = "Uma garota está esperando, esperando que você retribua seu último desejo a ela.",
  [646721411552256] = "Você encontra uma sala cheia de misticismo sobrenatural na cidade de Lamud, que acaba sendo uma cena de crime...",
  [646721411551744] = "Um estranho livro de pele humana aguarda a próxima pessoa a ser escolhida.",
  [646721411550976] = "As brasas da Guerra dos Deuses ainda não se extinguiram; a obsessão do Exilado ainda se apega à imagem sagrada do Louco.",
  [646721411550720] = "Você pode optar por ocultar certas partes cosméticas ao entrar no modo história em [Configurações] - [Gráficos] - [Efeitos Visuais].",
  [646721411550464] = "Decifrar os símbolos e utilizar as regras; cada símbolo aponta para a verdade final.",
  [646721411550208] = "Um ingresso cheio de pedidos de ajuda aponta para um teatro bizarro; você decide investigar...",
  [646721411549952] = "O maior dançarino da história versus o maior dançarino da era moderna – quem vencerá?",
  [646721411549696] = "Se a Bandeira da Conquista for capturada, o lado que desferir o golpe final receberá mais pontos Escolhidos por Deus.",
  [646721411549440] = "O lado defensor pode se teletransportar para o Corredor de Guerra a qualquer momento para retomar a Bandeira da Conquista.",
  [646721411549184] = "Assim que ambas as Bandeiras da Conquista forem ocupadas por qualquer lado atacante, o Portão da Guerra será aberto.",
  [646721411548672] = "Um truque está para ser executado; você pode resolver o quebra-cabeça do palhaço?",
  [646721411548416] = "O Submundo é um lugar especial esculpido pelo antigo Deus da Morte dentro do Mundo Espiritual.",
  [646721411548160] = "A Vela da Escuridão Eterna foi originalmente criada por Azik, mas mais tarde foi explorada por outros para se tornar uma ferramenta para manipular os aldeões para que sacrificassem suas vidas.",
  [646721411547904] = "Depois que o Ritual de Sacrifício foi interrompido por você e pelo Sr. Azik, o culpado fugiu para o Portão do Submundo...",
  [646721411547648] = "O destino final de todos os que morrem, o inferno escondido nas profundezas do Mundo Espiritual, a testemunha da decadência de todas as coisas – o reino pertencente exclusivamente ao Deus da Morte.",
  [646721411547392] = "Dica 7 do Gambito do Tolo (espaço reservado)",
  [646721411546880] = "Dica 5 do Gambito do Tolo (espaço reservado)",
  [646721411546624] = "Dica 4 do Gambito do Tolo (espaço reservado)",
  [646721411546368] = "Dica 3 do Gambito do Tolo (espaço reservado)",
  [646721411546112] = "Dica 2 do Fool's Gambit (espaço reservado)",
  [646721411545856] = "Dica 1 do Gambito do Tolo (espaço reservado)",
  [646721411543040] = "Quando jogadores da mesma Família participam de um masmorra , eles podem receber bônus de estatísticas e contagens extras de ressurreição.",
  [646721411542528] = "O criminoso procurado que cometeu o roubo está escondido em uma ruína subterrânea perto do Lago Golden Autumn. Prepare-se para a batalha final!",
  [646721411542272] = "Rozanne sugere que os novos funcionários da Blackthorn Security Company se familiarizem com Tingen o mais rápido possível; o manual do recém-chegado será bastante útil.",
  [646721411542016] = "Uma majestosa cidade de vapor, um conceito milagroso de pousar na Lua, uma sombra familiar e persistente de conhecimento...",
  [646721411541760] = "O covil de Abaddon, a fonte dos mortos-vivos. Acabe com tudo isso ou torne-se mais uma de suas coleções.",
  [646721411541504] = "Tingen enfrenta crise mais uma vez; o Vigias Noturnos usará Artefatos Selados para construir a barreira final.",
  [646721411541248] = "Um cadáver gigante bloqueia o caminho e atrás dele está o verdadeiro titereiro.",
  [646721411540992] = "A maré de cadáveres desce das montanhas como uma cachoeira. A morte segue como uma sombra; só existe um caminho para a sobrevivência.",
  [646721411540736] = "Nas ruínas subterrâneas abandonadas, os cultistas ainda vagam. No momento em que você cai em uma armadilha, os mortos já abriram os olhos.",
  [646721411540480] = "O avatar da ganância finalmente revela sua verdadeira face. Quebre seu escudo com moedas de ouro e acabe com sua loucura com um contrato.",
  [646721411540224] = "O cemitério dos indigentes, cheio de interrogatórios da humanidade. Antes que o tempo acabe, recue o destino que está prestes a ser destruído.",
  [646721411539968] = "Sob a máscara hipócrita do oficial de caridade existe um abismo de exploração. Resgate os trabalhadores e deixe a linha de execução terminar aqui.",
  [646721411539712] = "Todos os dias de pagamento na fábrica, as contas e os cobradores de dívidas de Locke sempre chegam na hora certa.",
  [646721411539456] = "Tingen Central Plaza, moedas de ouro como chuva. Pegue os presentes, evite as armadilhas; a tentação do capital nunca é gratuita.",
  [646721411539200] = "Desafiar um parceiro com quem você jurou um Pacto concederá bônus extras, como estatísticas, contagens de ressurreição e Marionete essência.",
  [646721411538944] = "Cada um dos corredores em camadas do teatro é uma recriação parcial da Marionete pequena cidade.",
  [646721411538688] = "Os fora de controle Marionetes retêm memórias de antes de suas mortes; coletar fragmentos de memória pode ajudar na sua investigação.",
  [646721411538432] = "O Teatro Utopia é um artefato selado relacionado às memórias do Sr. A Deusa Mãe está tentando corrompê-lo para influenciar Seu espírito...",
  [646721411538176] = "No modo duo, você pode fornecer fragmentos por meio do recurso [Memory Retrace] na interface de fragmentos de memória, que os jogadores dentro do masmorra podem pegar.",
  [646721411537920] = "O ataque de Zaratul afetou a pequena cidade Marionete, e todos Marionetes perderam o controle naquele momento.",
  [646721411535872] = "Os assentamentos de Guardiões com alto multiplicador são atualizados a cada 4 minutos após o início da partida; reivindicar a propriedade pode ganhar 4 ou 6 vezes mais pontos.",
  [646721411535616] = "No campo de batalha da Liga Quatro Vias, Caminho A supressão também é eficaz contra Guardiões Fantasmas.",
  [646721411535360] = "Os Phantom Guardians não podem ser curados, mas recuperarão lentamente a saúde quando não houver jogadores inimigos por perto.",
  [646721411535104] = "O Presidente, o Vice-Presidente e os membros do Conselho podem usar habilidades de comando para mudar o rumo da batalha e reescrever toda a partida!",
  [646721411534848] = "Aproveite os pontos no início para ganhar vantagem! O primeiro a matar um Guardião e reivindicar a propriedade ganha pontos extras!",
  [646721411534592] = "Durante o evento [Hunting Time], riscos e recompensas coexistem! Matar inimigos pode roubar o dobro dos pontos de classificação e vice-versa.",
  [646721411534336] = "Durante o evento [Hunting Time], derrotar os guardiões na Cidade Real pode render uma grande quantidade de Relíquia Escarlate materiais!",
  [646721411534080] = "Durante o evento [Hora de Caça], a invocação do Destino Marionetes será aberta no centro da Cidade Real.",
  [646721411533824] = "Ao carregar um Relíquia Escarlate , você pode ter se tornado alvo de outros caçadores; corra para encontrar o Mordomo Caçador para enviá-lo!",
  [646721411533568] = "O evento [Hunting Time] está aberto diariamente das 19h00 às 20h00, com abertura adicional nos finais de semana das 14h00 às 15h00.",
  [646721411533312] = "O Mordomo Caçador aparece aleatoriamente a cada meia hora. Quando a batalha for intensa, um segundo Mordomo Caçador aparecerá ao mesmo tempo!",
  [646721411533056] = "Na arena Final Hunt, equipes, grupos e outros membros do clube receberão proteção de combate; alianças de equipe não recebem proteção de combate!",
  [646721411532800] = "Bem-vindo ao Pico dos Deuses, onde você pegará em armas sob o olhar dos deuses, competirá pela glória e testemunhará o poder.",
  [646721411532544] = "Se a partida do Pico dos Deuses exceder um certo período de tempo, o poder de ataque aumentará.",
  [646721411532288] = "Antes do início do torneio Peak of the Gods, você pode votar no seu time favorito.",
  [646721411532032] = "Karl Edgar é obcecado por colecionar bonecas...",
  [646721411531776] = "Se você vir um olho vermelho maluco espiando você... por favor, tome cuidado!",
  [646721411531520] = "Diz-se que o conhecimento proibido que Karl Edgar espiou pode escravizar e controlar as mentes de outras criaturas.",
  [646721411531264] = "Recentemente, sons de arrepiar os cabelos foram ouvidos com frequência em um esgoto abandonado em Tingen...",
  [646721411530752] = "Há rumores de que todas as cidades arquivaram registros de incidentes fora de controle Beyonder, e esses arquivos nunca são facilmente mostrados a outras pessoas.",
  [646721411530496] = "A encantadora bruxa usa a reprodução como isca para atrair todas as coisas de volta ao eterno movimento fetal.",
  [646721411530240] = "As estratégias devem diferir quando equipes compostas por caminhos diferentes lutam; por exemplo, Aprendizes da 'Porta' Caminho são mais adequados para entrar correndo.",
  [646721411529984] = "Todos Beyonders no modo Batalha pelo Trono de Deus lutam usando os mesmos atributos reais que fazem fora do jogo.",
  [646721411529728] = "No modo Batalha pelo Trono de Deus, cada equipe tem 2 chances de ressuscitar companheiros caídos.",
  [646721411529472] = "Os Quatro Imperadores foram o Imperador Negro do Império Salomão, o Imperador de Sangue da Dinastia Tudor, o Imperador da Noite do Império Trunsoest e o Imperador da Morte do Continente Sul.",
  [646721411529216] = "A Guerra dos Quatro Imperadores foi uma guerra na Quarta Época que mudou a situação mundial, e os deuses participaram pessoalmente desta guerra.",
  [646721411528960] = "Pegar o trem a vapor permite chegar mais rapidamente às linhas de frente.",
  [646721411528704] = "Quando você estiver sozinho, você pode abrir o mapa para encontrar a localização dos membros de sua facção.",
  [646721411528448] = "Nos estágios iniciais de uma guerra de facções, ocupar e proteger sua própria Estela de Guerra é a estratégia mais importante.",
  [646721411528192] = "No mapa Snowy Mountain, Beyonders que chegarem perto da fonte em erupção serão afetados pelo efeito de controle de arremesso.",
  [646721411527936] = "Quando a partida do Dominator's Clash atingir um minuto e dois minutos, o poder de ataque aumentará; você pode usar esse efeito para vencer a partida.",
  [646721411527680] = "Quando você achar que é difícil matar um inimigo concentrando o fogo, proteger seus companheiros de equipe para atacá-los e vencer com base no dano causado pode ser uma boa estratégia.",
  [646721411527424] = "A força de Beyonders no modo Dominator's Clash é equilibrada e muito justa.",
  [646721411527168] = "Em cada jogo de Dominator's Clash, você pode usar duas poções especiais de recuperação.",
  [646721411526912] = "Durante a erupção da fonte no mapa Snowy Mountain, você pode pegar o presente da fonte que cai no chão para restaurar sua saúde.",
  [646721411526656] = "Este já foi o lugar onde um rei e uma rainha na história de Loen se apaixonaram.",
  [646721411526400] = "Quando você olha para esta pastagem do alto, você pode ver uma estrada em forma de coração.",
  [646721411526144] = "Este é um destino favorito para pessoas apaixonadas.",
  [646721411525888] = "Localizado no sopé da Serra Hornacis, este lugar apresenta um lindo mar de flores que floresce o ano todo.",
  [646721411525632] = "Beyonders dos \"Sleepless\" Caminho precisam influenciar os seres vivos ao redor cantando poemas.",
  [646721411525376] = "A caixa de ferro contendo o Artefato Selado precisa ser infundida com espiritualidade para ser ativada para uso.",
  [646721411525120] = "Artefato Selado de \"Grau 2\", perigoso, deve ser usado com cautela e moderação...",
  [646721411524864] = "Cada vez que a família Abraham aparece, eles perseguem as relíquias da família Antígono.",
  [646721411524608] = "O Artefato Selado '2-049' deixará as pessoas ao seu redor lentas; preste atenção aos movimentos de seus companheiros e resgate-os a tempo!",
  [646721411524352] = "Ray Bieber é um joalheiro Tingen com um salário semanal de cerca de 1 libra e 15 xelins.",
  [646721411524096] = "Ao encontrar um descendente da família Antigonus, o Artefato Selado '2-049' ficará muito animado e suas habilidades melhorarão significativamente.",
  [646721411523840] = "A família Antígono teve um status proeminente no Império Salomão da Quarta Época, mas esta história está envolta em névoa...",
  [646721411523584] = "As notas da família Antigonus já foram propriedade da família Abraham, mas foram perdidas devido a um acidente.",
  [646721411523328] = "A Terra Abandonada dos Deuses nasceu após a queda do Antigo Deus Sol e é uma região envolta em trevas.",
  [646721411523072] = "O lugar sagrado onde o Antigo Deus Sol despertou tem outro nome, chamado _______.",
  [646721411522816] = "O céu aqui não tem sol, apenas escuridão constante e relâmpagos que destroem tudo.",
  [646721411522560] = "O Lobo Demoníaco Negro é muito bom em se esconder e entende os métodos de sobrevivência do Vidente Caminho, até conhecer o Louco.",
  [646721411522304] = "\"Anjo do Destino\" Ouroboros, Rei dos Anjos do Destino Caminho, seguidor do Antigo Deus Sol.",
  [646721411522048] = "A escuridão durou dois mil anos. Até que o grande Louco respondeu às orações dos moradores da Cidade de Prata.",
  [646721411521792] = "Deus deixou uma maldição: todos aqueles que estão prestes a morrer se transformarão em espíritos malignos. A menos que eles sejam liquidados por seus próprios parentes.",
  [646721411521536] = "A concha do \"Anjo Negro\" Sasrir dorme na Corte do Rei Gigante, tendo sido erodida pelo Mar do Caos.",
  [646721411521280] = "A intenção original de estabelecer a Redenção da Rosa era salvá-lo assassinando-o.",
  [646721411521024] = "A Rose Redemption, uma organização secreta nascida na Terceira Época, tinha como membros o Anjo da Guerra e o Anjo do Destino.",
  [646721411520768] = "“Eu não traí a Cidade de Prata...” As palavras ditas uma vez se dissiparam no crepúsculo.",
  [646721411520512] = "A Cidade de Prata originou-se do Reino de Prata sob o governo da Corte do Rei Gigante, e eles acreditavam na Rainha Gigante, 'Deusa da Colheita' Omebella.",
  [646721411520256] = "Depois que Sasrir caiu em um sono profundo, Milgongen passou a guardar a Corte do Rei Gigante.",
  [646721411520000] = "Milgongen, intitulado 'God-Slayer', o líder dos Royal Court Hunters, mais tarde seguiu o Dark Angel Sasrir.",
  [646721411519744] = "A Rainha Misteriosa Bernadette disse que o 'Deus do Combate' é um gigante que sobreviveu desde os tempos antigos.",
  [646721411519488] = "Picos imponentes, enormes muralhas da cidade e um palácio eternamente banhado pelo brilho do crepúsculo – esta é a Corte do Rei Gigante.",
  [646721411519232] = "Os Feynapotters fluem com o sangue de gigantes e muitas vezes sonham com a Corte do Rei Gigante.",
  [646721411518976] = "Milhares de anos se passaram e os gigantes procuram sua cidade natal. Esta estrada nunca irá parar a menos que chegue ao fim.",
  [646721411518720] = "Entre os gigantes, o sinônimo de ‘traidor’ é Soniathrym.",
  [646721411518464] = "O tempo congela aqui e o mundo está sempre no crepúsculo. Bem-vindo à Corte do Rei Gigante!",
  [646721411518208] = "Um tutor chamado Ted foi convidado para a mansão, mas afirmou ter uma maneira de tratar o jovem visconde.",
  [646721411517952] = "Existem cães ferozes em May Manor; por favor, não toque neles e alimente-os com maçãs, se necessário.",
  [646721411517696] = "Sob a zombaria do destino, uma sombra vermelho-sangue gradualmente envolveu May Manor.",
  [646721411517440] = "Uma doença hereditária levou o marido da Viscondessa e levará o filho dela.",
  [646721411517184] = "A órfã cega entrega uma maçã ao seu companheiro doente: Não tenha medo, o próximo jogo está prestes a começar.",
  [646721411516928] = "O som de um batimento cardíaco vem das profundezas da mansão, e um guardião escarlate e misterioso vagueia sob as árvores.",
  [646721411516672] = "O leal mordomo protegerá a família Wetherell para sempre, mesmo que isso signifique usar o conhecimento ou a vida.",
  [646721411516416] = "Baldwin Wetherell, o dono da Armadura Ancestral, participou da Guerra do Juramento Quebrado e recebeu inúmeras recompensas após seu retorno triunfante.",
  [646721411516160] = "Miss Mud e Visconde Brick são uma combinação perfeita; eles construíram uma nova casa, a nova May Manor.",
  [646721411515904] = "Um dia, a vingança da nobreza destruiu tudo e apenas Dona Helena sobreviveu.",
  [646721411515648] = "A família do Visconde abre o solar todo mês de maio para convidar os moradores do território a compartilhar a fragrância.",
  [646721411515392] = "Todo mês de maio, a mansão repleta de macieiras fica cheia de fragrâncias.",
  [646721411515136] = "Antes do anoitecer, as pessoas voltam para casa; se você estiver fora neste horário, provavelmente encontrará eventos sobrenaturais.",
  [646721411514880] = "Agora, depois que Azik acorda, ele começa a viajar em busca do passado e também escreve cartas-resposta para Klein.",
  [646721411514624] = "Durante o sono de Azik, Klein continuou escrevendo cartas para ele.",
  [646721411514112] = "Azik Eggers perde a memória toda vez que acorda e, com o passar do tempo, ele se recupera gradualmente antes de morrer novamente.",
  [646721411513856] = "Como sua alma estava dividida, Azik Eggers caiu em um ciclo de morte e ressurreição.",
  [646721411513600] = "O porão do castelo está enterrado com o descendente de um certo deus, que também é filho de Azik Eggers.",
  [646721411513344] = "O salão do castelo é alto e amplo, mas mal iluminado, com janelas pequenas e altas, pilares de pedra que sustentam a cúpula e uma entrada escondida no porão.",
  [646721411513088] = "A estrutura principal do castelo mantém as características arquitetónicas do final da Quarta Época ao início da Quinta Época.",
  [646721411512832] = "Hoje, as paredes externas do Castelo Lamud desabaram e estão cobertas de vegetação.",
  [646721411512576] = "Existem pousadas e igrejas aqui, e a maioria dos residentes acredita na Deusa da Meia Noite.",
  [646721411512320] = "O Castelo Lamud fica em uma colina gramada, cercado por arbustos densos.",
  [646721411512064] = "Este castelo pertencia ao senhor que governou a cidade de Lamud no final da Quarta Época.",
  [646721411511808] = "O retrato do primeiro Barão Lamud foi descoberto aqui.",
  [646721411511552] = "Nas profundezas das montanhas, existia uma Cidade dos Mortos que coexistia com a Terra dos Vivos.",
  [646721411511296] = "Esta é a fronteira entre o Reino Loen e a República Intis.",
  [646721411511040] = "Havia vestígios de habitação humana no pico principal e um dia os moradores evaporaram instantaneamente.",
  [646721411510784] = "A civilização aqui respeita e teme a noite.",
  [646721411510528] = "\"Terra da Noite\" foi estabelecida pelos descendentes de deuses antigos e agora foi destruída.",
  [646721411510272] = "Diz a lenda que o tesouro secreto do renascimento da família Antigonus está escondido aqui.",
  [646721411510016] = "Era uma vez uma existência de alto nível que cruzou o mar e estabeleceu um reino secreto aqui: o Reino da Noite.",
  [646721411509760] = "A Cordilheira Hornacis já escondeu algum tipo de criatura mítica fora de controle.",
  [646721411509504] = "O pico principal de Hornacis já teve mais de 6.000 metros de altura, mas um dia desabou.",
